types.text:
interface EnableWhenCondition {
    id: string;
    question: string;
    operator: 'exists' | '=' | '!=' | '>' | '<' | '>=' | '<=' | 'contains';
    answer?: string | number;
}

interface FormSchema {
    formId: string;
    formVersionId: string;
    title: string;
    description?: string;
    blocks: Block[];
    schemaVersion?: number;
    navigation?: NavigationSettings;
    drafts?: DraftsSettings;
}

interface GridBlock extends LeafBlock {
    type: 'grid';
    rows: Option[];
    columns: GridColumn[];
}

type GridColumn = {
    code: string;
    label: string;
    type: 'radio';
    options: Option[];
    required?: boolean;
} | {
    code: string;
    label: string;
    type: 'dropdown';
    options: Option[];
    required?: boolean;
} | {
    code: string;
    label: string;
    type: 'text';
    required?: boolean;
};

interface GroupBlock {
    id: string;
    type: 'group';
    label: string;
    enableWhen?: EnableWhenCondition[];
    enableBehavior?: 'all' | 'any';
    enableLogic?: LogicNode;
    repeats?: boolean;
    repeatLabel?: string;
    minOccurs?: number;
    maxOccurs?: number;
    scores?: Score[];
    blocks: Block[];
}

interface LeafBlock {
    id: string;
    type: string;
    label: string;
    description?: string;
    content?: string;
    captions?: string;
    required?: boolean;
    completeRequired?: boolean;
    placeholder?: string;
    min?: number;
    max?: number;
    level?: number;
    options?: Option[];
    columns?: Option[];
    enableWhen?: EnableWhenCondition[];
    enableBehavior?: 'all' | 'any';
    enableLogic?: LogicNode;
}

type LogicNode = {
    all: LogicItem[];
} | {
    any: LogicItem[];
};

interface NavigationSettings {
    showProgress?: boolean;
    progressStyle?: ProgressStyle;
    reviewPage?: boolean;
}

interface Option {
    code: string;
    label: string;
    score?: number;
}

interface PageBlock {
    id: string;
    type: 'page';
    title: string;
    enableWhen?: EnableWhenCondition[];
    enableBehavior?: 'all' | 'any';
    enableLogic?: LogicNode;
    blocks: Block[];
}
